(function (global) {
    function randomBetween(min, max) {
        return min + Math.random() * (max - min);
    }

    function FinisherHeader(config) {
        this.config = config || {};
        this.container = document.querySelector(this.config.target || ".finisher-header");
        if (!this.container) return;

        this.canvas = document.createElement("canvas");
        this.canvas.className = "finisher-canvas";
        this.canvas.setAttribute("aria-hidden", "true");
        this.ctx = this.canvas.getContext("2d");
        this.particles = [];
        this.frame = null;
        this.dpr = Math.min(global.devicePixelRatio || 1, 2);
        this.reducedMotion = global.matchMedia && global.matchMedia("(prefers-reduced-motion: reduce)").matches;

        this.container.insertBefore(this.canvas, this.container.firstChild);
        this.resize = this.resize.bind(this);
        this.animate = this.animate.bind(this);
        global.addEventListener("resize", this.resize);
        this.resize();
        this.animate();
    }

    FinisherHeader.prototype.getSize = function () {
        var size = this.config.size || {};
        return randomBetween(size.min || 6, size.max || 28);
    };

    FinisherHeader.prototype.createParticle = function () {
        var speed = this.config.speed || {};
        var speedX = speed.x || {};
        var speedY = speed.y || {};
        var colors = (this.config.colors && this.config.colors.particles) || ["#2563eb"];

        return {
            x: randomBetween(-this.width * 0.1, this.width * 1.1),
            y: randomBetween(0, this.height),
            size: this.getSize(),
            vx: randomBetween(speedX.min || -0.2, speedX.max || 1.4) * (Math.random() > 0.35 ? 1 : -1),
            vy: randomBetween(speedY.min || -0.12, speedY.max || 0.16) * (Math.random() > 0.5 ? 1 : -1),
            angle: randomBetween(0, Math.PI),
            spin: randomBetween(-0.008, 0.008),
            alpha: randomBetween(0.35, 0.9),
            pulse: randomBetween(0, Math.PI * 2),
            color: colors[Math.floor(Math.random() * colors.length)]
        };
    };

    FinisherHeader.prototype.seed = function () {
        var count = this.config.count || 10;
        this.particles = [];
        for (var i = 0; i < count; i += 1) {
            this.particles.push(this.createParticle());
        }
    };

    FinisherHeader.prototype.resize = function () {
        var rect = this.container.getBoundingClientRect();
        this.width = Math.max(1, rect.width);
        this.height = Math.max(1, rect.height);
        this.canvas.width = this.width * this.dpr;
        this.canvas.height = this.height * this.dpr;
        this.canvas.style.width = this.width + "px";
        this.canvas.style.height = this.height + "px";
        this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
        this.seed();
    };

    FinisherHeader.prototype.drawBackground = function () {
        var colors = this.config.colors || {};
        if (!colors.background) return;

        var gradient = this.ctx.createLinearGradient(0, 0, this.width, this.height);
        gradient.addColorStop(0, colors.background);
        gradient.addColorStop(0.58, colors.backgroundAlt || colors.background);
        gradient.addColorStop(1, colors.backgroundEnd || colors.background);
        this.ctx.fillStyle = gradient;
        this.ctx.fillRect(0, 0, this.width, this.height);
    };

    FinisherHeader.prototype.drawParticle = function (particle, index) {
        var ctx = this.ctx;
        var pulse = 1 + Math.sin(particle.pulse) * 0.08;
        var size = particle.size * pulse;

        ctx.save();
        ctx.translate(particle.x, particle.y);
        ctx.rotate(particle.angle);
        ctx.globalAlpha = particle.alpha;
        ctx.fillStyle = particle.color;
        ctx.shadowColor = particle.color;
        ctx.shadowBlur = size * 0.7;

        if (index % 3 === 0) {
            ctx.fillRect(-size / 2, -size / 2, size, size);
        } else {
            ctx.beginPath();
            ctx.rect(-size / 2, -size / 2, size, size);
            ctx.fill();
        }

        ctx.restore();
    };

    FinisherHeader.prototype.updateParticle = function (particle) {
        particle.x += particle.vx;
        particle.y += particle.vy;
        particle.angle += particle.spin;
        particle.pulse += 0.025;

        if (particle.x > this.width + particle.size) particle.x = -particle.size;
        if (particle.x < -particle.size) particle.x = this.width + particle.size;
        if (particle.y > this.height + particle.size) particle.y = -particle.size;
        if (particle.y < -particle.size) particle.y = this.height + particle.size;
    };

    FinisherHeader.prototype.animate = function () {
        var ctx = this.ctx;
        if (!ctx) return;

        ctx.clearRect(0, 0, this.width, this.height);
        this.drawBackground();
        ctx.globalCompositeOperation = this.config.blending || "source-over";

        for (var i = 0; i < this.particles.length; i += 1) {
            if (!this.reducedMotion) this.updateParticle(this.particles[i]);
            this.drawParticle(this.particles[i], i);
        }

        ctx.globalCompositeOperation = "source-over";
        if (!this.reducedMotion) this.frame = global.requestAnimationFrame(this.animate);
    };

    FinisherHeader.prototype.destroy = function () {
        if (this.frame) global.cancelAnimationFrame(this.frame);
        global.removeEventListener("resize", this.resize);
        if (this.canvas && this.canvas.parentNode) this.canvas.parentNode.removeChild(this.canvas);
    };

    global.FinisherHeader = FinisherHeader;
})(window);
